"use client";

import Link from "next/link";
import { useMemo, useState } from "react";

type Term = { term: string; area: string; definition: string; distinction: string; related?: { label: string; slug: string }[] };

const terms: Term[] = [
{term:"Abduzione",area:"Logica e metodo",definition:"Forma di inferenza che propone un’ipotesi capace di spiegare un fatto osservato. Non dimostra che l’ipotesi sia vera: indica una spiegazione da mettere alla prova.",distinction:"Diversamente dalla deduzione, non garantisce la conclusione; diversamente dall’induzione, cerca spesso la migliore spiegazione disponibile.",related:[{label:"Abduzione",slug:"abduzione"},{label:"Conoscenza",slug:"conoscenza"}]},
{term:"Alienazione",area:"Etica, politica e società",definition:"Condizione in cui individui o gruppi si trovano separati dal controllo sulle proprie attività, dai loro prodotti, dagli altri o dalle proprie possibilità. Il significato cambia profondamente da Hegel a Marx e alle teorie successive.",distinction:"Non coincide con un semplice disagio psicologico: può indicare una struttura sociale e storica.",related:[{label:"Alienazione",slug:"alienazione"}]},
{term:"Anātman (non-sé)",area:"India e buddhismo",definition:"Dottrina buddhista secondo cui non esiste un sé permanente, autonomo e immutabile. La persona è descritta attraverso processi e aggregati condizionati, soggetti al mutamento.",distinction:"Non equivale semplicemente a negare l’esistenza convenzionale della persona; mette in discussione l’idea di un’identità sostanziale.",related:[{label:"Śūnyatā",slug:"sunyata"},{label:"Dharma",slug:"dharma"}]},
{term:"Aporia",area:"Filosofia antica",definition:"Difficoltà teorica o impasse argomentativa in cui le risposte disponibili conducono a contraddizioni o problemi ulteriori. Nei dialoghi platonici può diventare il punto di partenza della ricerca.",distinction:"Non è soltanto ignoranza: è la consapevolezza articolata di un problema che resiste alle soluzioni immediate."},
{term:"A priori / a posteriori",area:"Conoscenza e metafisica",definition:"A priori indica ciò che può essere giustificato indipendentemente da una specifica esperienza; a posteriori ciò che dipende dall’esperienza. La distinzione riguarda soprattutto il fondamento della conoscenza.",distinction:"Non coincide automaticamente con innato/acquisito né con universale/particolare.",related:[{label:"Conoscenza",slug:"conoscenza"},{label:"Ragione",slug:"ragione"}]},
{term:"Atarassia",area:"Filosofia ellenistica",definition:"Imperturbabilità o assenza di turbamento, obiettivo etico di alcune scuole ellenistiche. Epicurei e scettici la interpretano in modi differenti e attraverso pratiche diverse.",distinction:"Non è insensibilità: indica una forma di equilibrio ottenuta mediante un lavoro sui desideri e sui giudizi."},
{term:"Autonomia",area:"Etica e politica",definition:"Capacità di darsi una legge o una regola, individualmente o collettivamente, invece di riceverla passivamente da un’autorità esterna. In Kant è centrale per la moralità.",distinction:"Non significa fare ciò che si vuole: l’autonomia implica una forma di normatività e responsabilità.",related:[{label:"Autonomia",slug:"autonomia"},{label:"Libertà",slug:"liberta"}]},
{term:"Causa",area:"Metafisica e scienza",definition:"Ciò in virtù di cui qualcosa accade, esiste o può essere spiegato. Le filosofie distinguono diversi tipi di causa: efficiente, materiale, formale e finale, oppure analizzano la causalità come relazione tra eventi.",distinction:"Causalità, regolarità e spiegazione non sono sinonimi: una successione costante non basta sempre a stabilire un nesso causale.",related:[{label:"Causalità",slug:"causalita"},{label:"Causa finale",slug:"causa-finale"}]},
{term:"Cogito",area:"Filosofia moderna",definition:"Formula abbreviata del percorso cartesiano che riconosce nel pensare un punto fermo: mentre dubito, non posso dubitare del fatto che sto pensando. Da qui Cartesio avvia la ricostruzione del sapere.",distinction:"Non è uno slogan secondo cui il pensiero crea la realtà; è un argomento sul fondamento e sulla certezza del soggetto pensante."},
{term:"Contratto sociale",area:"Filosofia politica",definition:"Modello teorico che spiega la legittimità dell’ordine politico attraverso un patto, reale o ipotetico, tra individui. Hobbes, Locke e Rousseau ne offrono versioni diverse.",distinction:"Non è necessariamente il racconto di un evento storico: spesso è un dispositivo per valutare autorità, diritti e obblighi.",related:[{label:"Contratto sociale",slug:"contratto-sociale"},{label:"Stato di natura",slug:"stato-di-natura"}]},
{term:"Dialettica",area:"Logica e metafisica",definition:"Metodo di indagine che procede attraverso domande, opposizioni e trasformazioni concettuali. In Platone è dialogo orientato alla conoscenza; in Hegel diventa il movimento interno delle determinazioni e delle loro tensioni.",distinction:"Non va ridotta alla formula scolastica tesi-antitesi-sintesi, che non rende adeguatamente la varietà degli usi storici.",related:[{label:"Dialettica",slug:"dialettica"}]},
{term:"Dharma (धर्म)",area:"India e buddhismo",definition:"Termine sanscrito dai significati molteplici: ordine, norma, dovere, insegnamento, realtà o fenomeno, secondo la tradizione e il contesto. Nell’induismo può indicare l’ordine etico-sociale; nel buddhismo anche l’insegnamento e gli elementi dell’esperienza.",distinction:"Non possiede una traduzione unica valida per tutte le scuole: va interpretato storicamente e contestualmente.",related:[{label:"Dharma",slug:"dharma"}]},
{term:"Empirismo",area:"Teoria della conoscenza",definition:"Famiglia di orientamenti secondo cui l’esperienza sensibile svolge un ruolo fondamentale nella formazione o giustificazione della conoscenza. Le sue versioni differiscono sul rapporto tra percezione, idee e ragione.",distinction:"Non equivale a rifiutare ogni ragionamento teorico: riguarda il ruolo epistemico attribuito all’esperienza.",related:[{label:"Conoscenza",slug:"conoscenza"},{label:"Percezione",slug:"percezione"}]},
{term:"Episteme",area:"Filosofia antica",definition:"Conoscenza stabile e fondata, distinta in vari contesti dalla doxa, l’opinione. In Platone e Aristotele il termine assume funzioni specifiche, legate alla dimostrazione e alla comprensione delle cause.",distinction:"Non coincide semplicemente con la scienza contemporanea: il suo significato dipende dal quadro antico in cui viene impiegato."},
{term:"Essere",area:"Metafisica",definition:"Il tema più generale della metafisica: che cosa significa che qualcosa è, quali modi dell’essere esistono e come si distinguono esistenza, essenza, sostanza e divenire.",distinction:"Essere non è sempre sinonimo di esistere: molte tradizioni distinguono il fatto che qualcosa sia dal modo in cui è.",related:[{label:"Essere",slug:"essere"},{label:"Esistenza",slug:"esistenza"}]},
{term:"Essenza",area:"Metafisica",definition:"Ciò per cui una cosa è quello che è, ossia l’insieme delle determinazioni considerate costitutive della sua identità. Le teorie essenzialiste e antiessenzialiste discutono se e in quale senso tali determinazioni siano necessarie.",distinction:"L’essenza non coincide con le proprietà accidentali né sempre con una definizione linguistica.",related:[{label:"Essenza",slug:"essenza"},{label:"Sostanza",slug:"sostanza"}]},
{term:"Eudaimonia",area:"Etica antica",definition:"Termine greco spesso tradotto con felicità o fioritura umana. In Aristotele indica una vita riuscita nel suo complesso, esercitata secondo virtù e ragione, non un semplice stato emotivo.",distinction:"Non corrisponde al piacere momentaneo: riguarda la forma complessiva di una vita.",related:[{label:"Felicità",slug:"felicita"},{label:"Virtù",slug:"virtu-etica"}]},
{term:"Fenomeno",area:"Conoscenza e metafisica",definition:"Ciò che appare o si manifesta all’esperienza. Nella filosofia kantiana il fenomeno è l’oggetto così come può essere conosciuto nelle condizioni della sensibilità e dell’intelletto.",distinction:"Non significa necessariamente apparenza ingannevole: ciò che appare può essere oggetto di conoscenza rigorosa."},
{term:"Fenomenologia",area:"Filosofia contemporanea",definition:"Movimento e metodo filosofico che descrive le strutture dell’esperienza così come si danno alla coscienza, prestando attenzione a intenzionalità, percezione, temporalità e mondo vissuto.",distinction:"Non è una psicologia empirica né una semplice raccolta di impressioni soggettive.",related:[{label:"Coscienza",slug:"coscienza"},{label:"Intenzionalità",slug:"intenzionalita"}]},
{term:"Giustizia",area:"Etica e politica",definition:"Principio e problema relativo a ciò che è dovuto a ciascuno, alla distribuzione di beni e oneri, al riconoscimento, alle procedure e alla legittimità delle istituzioni.",distinction:"Giustizia distributiva, retributiva, procedurale e riparativa affrontano questioni differenti e non sempre sovrapponibili.",related:[{label:"Giustizia",slug:"giustizia"},{label:"Uguaglianza",slug:"uguaglianza"}]},
{term:"Ideologia",area:"Etica, politica e società",definition:"Insieme organizzato di idee, rappresentazioni e valori che interpreta la società e può legittimare o contestare rapporti di potere. In Marx il termine assume una critica specifica delle forme di coscienza legate ai rapporti sociali.",distinction:"Non indica soltanto un’opinione falsa: gli usi contemporanei comprendono anche sistemi di orientamento politico e culturale.",related:[{label:"Ideologia",slug:"ideologia"},{label:"Potere",slug:"potere"}]},
{term:"Immanenza / trascendenza",area:"Metafisica e religione",definition:"Immanente è ciò che resta interno a un ordine o alla realtà considerata; trascendente ciò che lo oltrepassa. La distinzione è impiegata in metafisica, teologia e filosofia politica.",distinction:"I due termini cambiano significato secondo ciò rispetto a cui qualcosa è detto interno o oltrepassante."},
{term:"Induzione",area:"Logica e metodo",definition:"Inferenza che parte da casi osservati per formulare generalizzazioni o aspettative su casi non osservati. Le conclusioni sono ampliative e non possiedono la necessità formale della deduzione.",distinction:"Una generalizzazione induttiva resta rivedibile alla luce di nuove osservazioni.",related:[{label:"Induzione",slug:"induzione"},{label:"Conoscenza",slug:"conoscenza"}]},
{term:"Intenzionalità",area:"Filosofia della mente",definition:"Carattere per cui stati mentali e atti di coscienza sono diretti verso qualcosa: si pensa, desidera, ricorda o teme qualcosa. Il concetto è centrale nella scolastica e nella fenomenologia.",distinction:"Non coincide con l’intenzione deliberata: anche percezioni e credenze possono essere intenzionali.",related:[{label:"Intenzionalità",slug:"intenzionalita"},{label:"Coscienza",slug:"coscienza"}]},
{term:"Logos (λόγος)",area:"Grecia antica",definition:"Parola greca che può significare discorso, ragione, argomento, proporzione o principio intelligibile. Nei presocratici, in Platone, negli stoici e nel pensiero cristiano assume funzioni differenti.",distinction:"Tradurlo sempre con “ragione” o sempre con “parola” cancella la pluralità dei suoi usi.",related:[{label:"Logos",slug:"logos"},{label:"Ragione",slug:"ragione"}]},
{term:"Māyā (माया)",area:"India",definition:"Concetto di diverse tradizioni indiane, particolarmente rilevante in alcune scuole vedāntiche, associato alla potenza di manifestazione e alla percezione del mondo come molteplice. Le interpretazioni non sono uniformi.",distinction:"Non va tradotto senza cautele come “illusione”: può indicare un principio cosmologico o una modalità di apparire."},
{term:"Metafisica",area:"Metafisica",definition:"Indagine sui principi e sulle strutture più generali della realtà: essere, sostanza, causalità, possibilità, identità, tempo e fondamento. Le sue domande variano tra le tradizioni.",distinction:"Non è sinonimo di soprannaturale: comprende anche analisi concettuali della realtà ordinaria."},
{term:"Mimesi",area:"Estetica e filosofia dell’arte",definition:"Nozione greca di imitazione o rappresentazione, centrale nelle riflessioni antiche su poesia, arti e conoscenza. Platone e Aristotele ne danno valutazioni e interpretazioni differenti.",distinction:"Non significa necessariamente copia fedele: può implicare selezione, configurazione e comprensione del reale."},
{term:"Nirvāṇa (निर्वाण)",area:"India e buddhismo",definition:"Fine della brama, dell’ignoranza e delle condizioni che alimentano la sofferenza e il ciclo della rinascita, secondo le tradizioni buddhiste. Il concetto è elaborato in modi diversi nelle scuole.",distinction:"Non è semplicemente un luogo paradisiaco né può essere ridotto a un annientamento individuale."},
{term:"Noumeno",area:"Filosofia moderna",definition:"In Kant indica la cosa considerata indipendentemente dalle condizioni della nostra intuizione sensibile, come concetto-limite rispetto alla conoscenza possibile.",distinction:"Non è un oggetto nascosto che la ragione possa descrivere liberamente: segnala un limite della conoscenza teoretica."},
{term:"Ontologia",area:"Metafisica",definition:"Indagine sull’essere e sui modi fondamentali in cui le cose esistono: oggetti, proprietà, relazioni, eventi, processi e categorie. Il termine si consolida nella filosofia moderna.",distinction:"È spesso considerata parte della metafisica, ma i confini tra i due ambiti variano secondo gli autori."},
{term:"Parrēsia (παρρησία)",area:"Etica e politica",definition:"Pratica del parlare franco: dire ciò che si ritiene vero assumendosi un rischio e una responsabilità nei confronti di chi ascolta. È importante nelle analisi antiche e nella lettura di Foucault.",distinction:"Non equivale a dire qualsiasi cosa senza riguardo: implica un rapporto etico tra verità, coraggio e rischio."},
{term:"Percezione",area:"Filosofia della mente",definition:"Processo attraverso cui un soggetto entra in rapporto sensibile con il mondo. La filosofia indaga il rapporto tra dati sensoriali, organizzazione, interpretazione e realtà percepita.",distinction:"Percepire non è semplicemente ricevere stimoli: coinvolge strutture corporee, cognitive e ambientali.",related:[{label:"Percezione",slug:"percezione"}]},
{term:"Pratītyasamutpāda (origine dipendente)",area:"India e buddhismo",definition:"Principio buddhista secondo cui i fenomeni sorgono in dipendenza da condizioni e relazioni, non in modo isolato o autosufficiente. È centrale per comprendere la spiegazione della sofferenza e la critica della sostanzialità.",distinction:"Non è un semplice determinismo lineare: descrive reti di condizionamento e dipendenza.",related:[{label:"Dharma",slug:"dharma"},{label:"Śūnyatā",slug:"sunyata"}]},
{term:"Ragione",area:"Conoscenza e metafisica",definition:"Facoltà o pratica del pensare secondo nessi, argomenti e criteri di giustificazione. Le filosofie discutono se sia universale, storicamente situata, strumentale, critica o dialogica.",distinction:"Non coincide sempre con il calcolo: può includere giudizio, interpretazione e riflessione sui fini.",related:[{label:"Ragione",slug:"ragione"}]},
{term:"Relativismo",area:"Conoscenza, etica e cultura",definition:"Famiglia di tesi secondo cui verità, valori o criteri di giustificazione dipendono da quadri culturali, linguistici, storici o concettuali. Esistono forme diverse e non equivalenti di relativismo.",distinction:"Riconoscere la pluralità delle prospettive non comporta automaticamente sostenere che tutte le opinioni siano ugualmente valide.",related:[{label:"Relativismo",slug:"relativismo"},{label:"Pluralismo",slug:"pluralismo"}]},
{term:"Samsāra (संसार)",area:"India e buddhismo",definition:"Ciclo delle rinascite e dell’esistenza condizionata, presente in diverse tradizioni indiane. Le interpretazioni del suo funzionamento e delle vie di liberazione variano tra induismo, buddhismo e jainismo.",distinction:"Non è una semplice ripetizione quotidiana: riguarda una concezione più ampia della condizione esistenziale e cosmica."},
{term:"Sostanza",area:"Metafisica",definition:"Ciò che sussiste o costituisce il soggetto fondamentale di proprietà e mutamenti. Aristotele, Cartesio, Spinoza e le filosofie successive ne propongono concezioni profondamente differenti.",distinction:"Non va intesa soltanto come materia fisica: può designare un principio ontologico.",related:[{label:"Sostanza",slug:"sostanza"}]},
{term:"Śūnyatā (शून्यता, vacuità)",area:"India e buddhismo",definition:"Concetto centrale del buddhismo mahāyāna, soprattutto nella tradizione madhyamaka: i fenomeni sono vuoti di esistenza intrinseca e indipendente perché sorgono in dipendenza da condizioni.",distinction:"Vacuità non significa nulla assoluto o inesistenza: indica l’assenza di natura propria autonoma.",related:[{label:"Śūnyatā",slug:"sunyata"},{label:"Dharma",slug:"dharma"}]},
{term:"Teleologia",area:"Metafisica e filosofia della natura",definition:"Spiegazione o interpretazione dei processi in riferimento a fini, scopi o stati verso cui tenderebbero. È centrale nella filosofia aristotelica e viene ripensata o criticata nella modernità.",distinction:"Una spiegazione teleologica non coincide necessariamente con l’attribuzione di intenzioni coscienti alla natura.",related:[{label:"Teleologia",slug:"teleologia"},{label:"Causa finale",slug:"causa-finale"}]},
{term:"Utilitarismo",area:"Etica",definition:"Teoria morale che valuta azioni, regole o istituzioni in base alle conseguenze per il benessere. Le versioni classiche sono associate a Bentham e Mill; le elaborazioni successive distinguono utilità, preferenze e forme di benessere.",distinction:"Non significa perseguire il proprio interesse: il criterio classico considera imparzialmente gli interessi di tutti i soggetti coinvolti."},
{term:"Virtù",area:"Etica",definition:"Disposizione stabile a sentire, giudicare e agire in modo eccellente. Nelle etiche antiche è legata alla formazione del carattere e alla vita buona; altre tradizioni ne riformulano il ruolo.",distinction:"La virtù non è un singolo atto corretto, ma una disposizione acquisita e relativamente stabile.",related:[{label:"Virtù",slug:"virtu-etica"},{label:"Felicità",slug:"felicita"}]},
{term:"Volontà",area:"Etica e filosofia della mente",definition:"Facoltà o dimensione dell’agire legata a desiderio, decisione, scelta e impegno. La filosofia discute il rapporto tra volontà, ragione, libertà, necessità e responsabilità.",distinction:"Volere, desiderare e scegliere possono essere fenomeni distinti, anche quando si intrecciano.",related:[{label:"Libertà",slug:"liberta"},{label:"Responsabilità",slug:"responsabilita"}]},
{term:"Wu wei (無為)",area:"Cina",definition:"Espressione taoista spesso resa come “non-agire” o “agire senza forzatura”. Indica un modo di operare in sintonia con il corso delle cose, evitando interventi rigidi e artificiosi.",distinction:"Non significa inerzia o passività: può descrivere un’efficacia non coercitiva e non forzata.",related:[{label:"Dao",slug:"dao"}]},
{term:"Yin e yang (陰陽)",area:"Cina",definition:"Polarità correlate attraverso cui la tradizione cinese descrive processi e trasformazioni: ricettività e attività, ombra e luce, contrazione ed espansione. Non sono sostanze isolate né una divisione morale tra bene e male.",distinction:"I due poli sono interdipendenti e trasformabili, non opposizioni assolute.",related:[{label:"Dao",slug:"dao"}]},
{term:"Ziran (自然)",area:"Cina",definition:"Concetto taoista traducibile, con cautela, come spontaneità o “essere-così-da-sé”. Indica ciò che si sviluppa secondo il proprio corso, senza imposizione artificiale.",distinction:"Non equivale a una nozione moderna di natura contrapposta alla cultura: riguarda anche il modo spontaneo dell’accadere.",related:[{label:"Dao",slug:"dao"}]},
{term:"Abiezione",area:"Etica, politica e società",definition:"Condizione di espulsione o degradazione attraverso cui un soggetto o un gruppo viene collocato fuori dai confini del riconoscimento sociale. Il concetto è stato sviluppato soprattutto nella teoria critica e nella riflessione femminista.",distinction:"Non coincide con la povertà materiale: riguarda anche i confini simbolici che definiscono ciò che una comunità considera accettabile."},
{term:"Accidente",area:"Metafisica",definition:"Proprietà che può appartenere a una cosa senza costituire ciò che essa è essenzialmente. Nella tradizione aristotelica l'accidente si predica di un soggetto e può mutare senza che il soggetto cessi necessariamente di essere ciò che è.",distinction:"Si oppone all'essenza, ma la distinzione dipende dalla teoria della sostanza adottata."},
{term:"Adeguazione",area:"Teoria della conoscenza",definition:"Relazione di corrispondenza tra una conoscenza e il suo oggetto, spesso impiegata nelle definizioni classiche della verità.",distinction:"Non è una spiegazione completa della verità: teorie coerentiste, pragmatiche e deflazioniste la interpretano diversamente."},
{term:"Aletheia",area:"Filosofia antica",definition:"Termine greco tradotto come verità, disvelamento o non-nascondimento. In alcuni contesti filosofici indica il manifestarsi di ciò che è, oltre la semplice correttezza di una proposizione.",distinction:"Non va usato come sinonimo universale di verità: le interpretazioni, soprattutto in Heidegger, sono specifiche."},
{term:"Anamnesi",area:"Filosofia antica",definition:"In Platone, processo di reminiscenza attraverso cui l'anima riconosce verità che non derivano soltanto dall'esperienza presente. Il concetto collega conoscenza, anima e apprendimento.",distinction:"Non coincide con il ricordo psicologico ordinario di un episodio passato."},
{term:"Anarchismo",area:"Filosofia politica",definition:"Famiglia di teorie che criticano il potere coercitivo e le gerarchie istituzionali, proponendo forme di organizzazione basate su autonomia, cooperazione e autogoverno.",distinction:"Non significa assenza di regole o disordine: molte correnti anarchiche elaborano forme complesse di coordinamento sociale."},
{term:"Antinomia",area:"Logica e metafisica",definition:"Conflitto tra due tesi apparentemente dimostrabili, ciascuna delle quali conduce a difficoltà quando viene assunta come assoluta. In Kant le antinomie riguardano i limiti della ragione nella cosmologia.",distinction:"Non è una semplice contraddizione formale: può rivelare un uso illegittimo di concetti oltre i limiti della loro applicazione."},
{term:"Antropocentrismo",area:"Etica e filosofia della natura",definition:"Orientamento che assume l'essere umano come centro o misura privilegiata del valore e dell'interpretazione del mondo.",distinction:"Si distingue dall'antropomorfismo, che attribuisce caratteristiche umane ad altri enti."},
{term:"Apatheia",area:"Filosofia ellenistica",definition:"Nello stoicismo indica la libertà dalle passioni intese come giudizi disordinati eccessivi, non l'assenza di ogni sentimento.",distinction:"Non equivale a freddezza emotiva: gli stoici distinguono le passioni viziose dagli affetti razionali."},
{term:"Arché",area:"Filosofia antica",definition:"Principio originario o fondamento da cui le cose derivano e attraverso cui si cerca di spiegare l'ordine del cosmo. I presocratici propongono risposte differenti.",distinction:"Non indica sempre un inizio cronologico: può essere principio strutturale o esplicativo."},
{term:"Arete",area:"Etica antica",definition:"Eccellenza o virtù: capacità di svolgere bene una funzione o realizzare pienamente una possibilità. In etica indica una disposizione stabile del carattere.",distinction:"Non coincide soltanto con la virtù morale nel senso moderno: il termine ha usi più ampi."},
{term:"Autopoiesi",area:"Filosofia della scienza e della mente",definition:"Concetto elaborato per descrivere sistemi capaci di produrre e mantenere la propria organizzazione attraverso processi interni di autoriproduzione.",distinction:"Non significa autosufficienza assoluta: un sistema autopoietico resta in rapporto con il proprio ambiente."},
{term:"Assiologia",area:"Etica e filosofia del valore",definition:"Indagine filosofica sulla natura dei valori, sulla loro gerarchia e sui modi in cui possono essere conosciuti o giustificati.",distinction:"Non coincide con l'etica: comprende anche valori estetici, epistemici e sociali."},
{term:"Bene",area:"Etica e metafisica",definition:"Concetto fondamentale che può indicare ciò che è desiderabile, ciò che perfeziona un ente o ciò che merita approvazione morale. Le tradizioni ne propongono concezioni diverse.",distinction:"Bene morale, bene utile e bene ontologico non sono necessariamente la stessa cosa."},
{term:"Bene comune",area:"Filosofia politica",definition:"Insieme di condizioni, istituzioni e beni condivisi che rendono possibile la vita buona dei membri di una comunità.",distinction:"Non coincide con la somma degli interessi privati né autorizza automaticamente a sacrificare i diritti individuali."},
{term:"Biopolitica",area:"Filosofia politica contemporanea",definition:"Analisi delle modalità con cui il potere amministra la vita, i corpi, la salute, la popolazione e i processi biologici.",distinction:"Non indica soltanto la politica sanitaria: riguarda le tecniche di governo della vita individuale e collettiva."},
{term:"Catarsi",area:"Estetica e filosofia antica",definition:"Termine associato alla tragedia nella Poetica di Aristotele, interpretato come purificazione, chiarificazione o regolazione delle emozioni di pietà e paura.",distinction:"Il significato preciso è discusso: non esiste una traduzione unanimemente accettata."},
{term:"Certezza",area:"Teoria della conoscenza",definition:"Condizione in cui una credenza è considerata immune da dubbio rilevante o sufficientemente giustificata. La filosofia distingue certezza psicologica, logica ed epistemica.",distinction:"Sentirsi certi non equivale a possedere una conoscenza certa."},
{term:"Cognitivismo",area:"Filosofia della mente",definition:"Approccio che studia la mente attraverso processi di rappresentazione, elaborazione dell'informazione e organizzazione cognitiva.",distinction:"Non è una singola teoria della mente e non implica necessariamente che il pensiero sia riducibile al calcolo."},
{term:"Comunitarismo",area:"Filosofia politica",definition:"Famiglia di posizioni che sottolinea il ruolo delle comunità, delle pratiche condivise e delle tradizioni nella formazione dell'identità e dei valori.",distinction:"Non è necessariamente ostile ai diritti individuali: critica soprattutto l'immagine dell'individuo isolato e astratto."},
{term:"Contingenza",area:"Metafisica",definition:"Carattere di ciò che è, ma avrebbe potuto non essere o essere altrimenti. Si contrappone alla necessità in diversi sistemi metafisici.",distinction:"Non equivale a casualità: un evento contingente può avere cause e spiegazioni."},
{term:"Contraddizione",area:"Logica",definition:"Relazione tra proposizioni incompatibili, tali che non possano essere entrambe vere nello stesso senso e nello stesso tempo.",distinction:"La contraddizione logica va distinta dal conflitto pratico o dalla tensione tra valori."},
{term:"Cosmologia",area:"Metafisica e filosofia della scienza",definition:"Indagine filosofica sull'origine, la struttura, l'ordine e l'evoluzione dell'universo. Può dialogare con la cosmologia scientifica senza coincidere con essa.",distinction:"Non è soltanto una teoria scientifica dell'universo: comprende anche questioni metafisiche e concettuali."},
{term:"Critica",area:"Metodo filosofico",definition:"Esame dei presupposti, dei limiti e delle condizioni di validità di una conoscenza, di una pratica o di un'istituzione.",distinction:"Non significa necessariamente rifiuto: la critica può chiarire e fondare meglio ciò che sottopone a esame."},
{term:"Deontologia",area:"Etica",definition:"Teoria morale che attribuisce valore centrale a doveri, norme e vincoli, indipendentemente dalla sola valutazione delle conseguenze.",distinction:"Non ogni etica del dovere è kantiana e non tutte le teorie deontologiche interpretano allo stesso modo le norme."},
{term:"Determinismo",area:"Metafisica e filosofia della scienza",definition:"Tesi secondo cui, date le condizioni e le leggi pertinenti, gli eventi sono fissati o necessitati da ciò che li precede.",distinction:"Non coincide automaticamente con il fatalismo: il determinismo riguarda il nesso tra condizioni e conseguenze."},
{term:"Dilemma",area:"Logica ed etica",definition:"Situazione argomentativa o pratica in cui si presentano alternative difficili, ciascuna delle quali comporta conseguenze problematiche.",distinction:"Un dilemma autentico non si risolve semplicemente scegliendo l'opzione più comoda: occorre chiarire valori e presupposti in conflitto."},
{term:"Diritto naturale",area:"Filosofia politica e giuridica",definition:"Concezione secondo cui esistono principi di giustizia o diritti fondati sulla natura umana, sulla ragione o su un ordine morale, non soltanto sulle leggi positive.",distinction:"Le teorie del diritto naturale divergono sul fondamento e sul contenuto di tali principi."},
{term:"Discorso",area:"Linguaggio e filosofia sociale",definition:"Pratica organizzata di enunciati, regole e istituzioni che definisce ciò che può essere detto, pensato e riconosciuto in un contesto storico.",distinction:"Non è sinonimo di conversazione: in alcune teorie indica strutture di sapere e potere."},
{term:"Elenchos",area:"Filosofia antica",definition:"Procedura socratica di confutazione che mette alla prova le convinzioni dell'interlocutore mostrando tensioni o incoerenze nelle sue risposte.",distinction:"Non è una confutazione aggressiva fine a se stessa: può servire a rendere consapevoli dei limiti del proprio sapere."},
{term:"Emancipazione",area:"Etica, politica e società",definition:"Processo di liberazione da rapporti di dipendenza, dominio o esclusione, attraverso il riconoscimento di capacità e diritti.",distinction:"Non coincide sempre con l'indipendenza individuale: può richiedere trasformazioni istituzionali e collettive."},
{term:"Emergentismo",area:"Filosofia della mente e della natura",definition:"Tesi secondo cui alcune proprietà o capacità emergono dall'organizzazione di sistemi complessi e non sono spiegabili soltanto enumerando le loro parti.",distinction:"Le versioni deboli e forti divergono sul grado di autonomia causale delle proprietà emergenti."},
{term:"Entelechia",area:"Metafisica e filosofia della natura",definition:"In Aristotele indica il compimento o l'attualità di ciò che possiede una forma e realizza la propria possibilità.",distinction:"Non è semplicemente uno scopo futuro: designa anche il principio attuale che rende un ente ciò che è."},
{term:"Epoche",area:"Filosofia ellenistica",definition:"Sospensione del giudizio praticata dallo scetticismo antico quando le ragioni contrapposte appaiono equivalenti o non decisive.",distinction:"Non significa rinunciare a ogni azione: lo scettico può seguire apparenze, consuetudini e pratiche senza assentire dogmaticamente."},
{term:"Ermeneutica",area:"Linguaggio e interpretazione",definition:"Teoria e pratica dell'interpretazione dei testi, delle azioni e delle espressioni umane. Nella filosofia contemporanea riguarda anche la storicità della comprensione.",distinction:"Non è soltanto una tecnica per interpretare testi antichi: investe il modo in cui comprendiamo il mondo."},
{term:"Esistenzialismo",area:"Filosofia contemporanea",definition:"Orientamento che pone al centro esistenza concreta, libertà, scelta, angoscia, responsabilità e finitezza. Include autori con posizioni anche molto diverse.",distinction:"Non è una dottrina unitaria né coincide con il pessimismo."},
{term:"Fatalismo",area:"Metafisica ed etica",definition:"Tesi secondo cui un esito si verificherà indipendentemente da ciò che gli agenti fanno o decidono.",distinction:"Va distinto dal determinismo, che non rende necessariamente irrilevanti le azioni: esse possono essere parte delle cause."},
{term:"Fideismo",area:"Filosofia della religione",definition:"Orientamento che attribuisce alla fede un ruolo fondamentale o non sostituibile dalla dimostrazione razionale nella conoscenza religiosa.",distinction:"Le forme di fideismo differiscono: non tutte rifiutano ogni uso della ragione."},
{term:"Finalismo",area:"Metafisica e filosofia della natura",definition:"Interpretazione dei processi in base a fini o stati di compimento verso cui tendono. È centrale in alcune filosofie antiche e medievali.",distinction:"Non implica sempre un progettista cosciente né coincide con la teleologia biologica contemporanea."},
{term:"Genealogia",area:"Metodo filosofico",definition:"Metodo di ricostruzione critica che indaga l'origine storica di valori, concetti e istituzioni, mostrando conflitti e trasformazioni che li hanno prodotti.",distinction:"Non cerca necessariamente un'origine pura: spesso mette in discussione l'idea stessa di un'origine semplice."},
{term:"Habitus",area:"Etica e filosofia sociale",definition:"Disposizione durevole, acquisita attraverso pratiche e condizioni sociali, che orienta percezioni, gusti e comportamenti.",distinction:"Non è un'abitudine isolata: riguarda schemi incorporati e socialmente formati."},
{term:"Identità",area:"Metafisica e filosofia sociale",definition:"Relazione per cui qualcosa resta se stesso nel tempo oppure viene riconosciuto come appartenente a un soggetto o gruppo. Può essere personale, narrativa, sociale o numerica.",distinction:"Identità numerica e identità qualitativa sono distinte: due cose possono somigliarsi senza essere la stessa cosa."},
{term:"Illuminismo",area:"Storia della filosofia",definition:"Movimento plurale che valorizza l'uso pubblico della ragione, la critica dell'autorità, la riforma delle istituzioni e la diffusione del sapere.",distinction:"Non è un fenomeno esclusivamente europeo né una corrente omogenea: esistono illuminismi e modernità differenti."},
{term:"Individuazione",area:"Metafisica e filosofia della mente",definition:"Processo attraverso cui un ente o un soggetto si costituisce come individuo distinto, con una propria unità e continuità.",distinction:"Non coincide semplicemente con la classificazione: riguarda il problema di che cosa renda singolare un ente."},
{term:"Intersoggettività",area:"Fenomenologia e filosofia sociale",definition:"Relazione tra soggetti attraverso cui si costituiscono comprensione reciproca, mondo condiviso e riconoscimento.",distinction:"Non è la semplice somma di esperienze private: riguarda le condizioni della condivisione."},
{term:"Ironia",area:"Filosofia antica e retorica",definition:"Figura e atteggiamento discorsivo in cui il significato espresso si distingue da quello inteso. Nell'ironia socratica può mettere alla prova pretese di sapere.",distinction:"Non è soltanto sarcasmo: può essere un metodo di interrogazione e distanziamento critico."},
{term:"Legittimità",area:"Filosofia politica",definition:"Qualità di un potere, di una norma o di un'istituzione riconosciuti come giustificati o autorizzati secondo criteri condivisi o argomentabili.",distinction:"Legalità e legittimità non coincidono: una norma può essere valida secondo il diritto positivo e tuttavia essere contestata moralmente."},
{term:"Materialismo",area:"Metafisica",definition:"Famiglia di teorie che attribuiscono alla materia o alla realtà fisica un ruolo fondamentale nella costituzione del mondo.",distinction:"Non è necessariamente riduzionismo: esistono materialismi che riconoscono livelli, processi e proprietà emergenti."},
{term:"Monismo",area:"Metafisica",definition:"Posizione secondo cui la realtà, in ultima analisi, dipende da un unico principio, sostanza o tipo fondamentale di realtà.",distinction:"Si distingue dal dualismo e dal pluralismo, ma esistono forme molto diverse di monismo."},
{term:"Nichilismo",area:"Metafisica, etica e cultura",definition:"Famiglia di posizioni che mettono in questione l'esistenza o la validità di fondamenti, valori e significati considerati assoluti.",distinction:"Non significa sempre negare ogni valore: Nietzsche, ad esempio, analizza il nichilismo come crisi storica dei valori supremi."},
{term:"Nominalismo",area:"Metafisica e linguaggio",definition:"Posizione secondo cui gli universali non esistono come entità indipendenti; i termini generali funzionano attraverso nomi, concetti o pratiche linguistiche.",distinction:"Le teorie nominaliste differiscono sullo statuto dei concetti e sulla spiegazione delle somiglianze."},
{term:"Normatività",area:"Etica e filosofia politica",definition:"Carattere di ciò che stabilisce criteri su come si dovrebbe pensare, agire o organizzare una pratica.",distinction:"Non coincide con la descrizione di ciò che accade: distingue fatti, regole e giustificazioni."},
{term:"Oggettività",area:"Teoria della conoscenza",definition:"Carattere di una conoscenza o valutazione che non dipende soltanto da preferenze individuali e può essere sottoposta a criteri condivisibili.",distinction:"Non richiede sempre un punto di vista privo di prospettiva: alcune teorie spiegano l'oggettività attraverso procedure e confronto."},
{term:"Ontoteologia",area:"Metafisica e filosofia della religione",definition:"Struttura di pensiero che interpreta l'essere attraverso un ente supremo assunto come fondamento ultimo e principio di intelligibilità.",distinction:"È una categoria critica della storia della metafisica, non una descrizione neutrale di ogni teologia."},
{term:"Panpsichismo",area:"Filosofia della mente",definition:"Tesi secondo cui la dimensione mentale o esperienziale è una caratteristica fondamentale e diffusa della realtà, non limitata agli organismi complessi.",distinction:"Non sostiene necessariamente che ogni cosa abbia coscienza umana o pensiero riflessivo."},
{term:"Paradosso",area:"Logica e filosofia",definition:"Enunciato o argomento che conduce a un risultato controintuitivo, apparentemente contraddittorio o difficile da conciliare con le convinzioni iniziali.",distinction:"Un paradosso può rivelare un errore, ma anche un limite nei concetti o nelle regole adottate."},
{term:"Pluralismo",area:"Metafisica, etica e politica",definition:"Posizione che riconosce una pluralità irriducibile di principi, valori, forme di vita o prospettive legittime.",distinction:"Non equivale a relativismo: il pluralista può sostenere criteri per valutare conflitti tra valori."},
{term:"Pragmatismo",area:"Filosofia contemporanea",definition:"Tradizione che collega il significato dei concetti alle conseguenze pratiche e interpreta la conoscenza attraverso indagine, esperienza e correzione degli errori.",distinction:"Non significa utilitarismo quotidiano o attenzione esclusiva al vantaggio immediato."},
{term:"Presupposto",area:"Metodo filosofico",definition:"Assunzione implicita o esplicita da cui dipende un ragionamento, una teoria o una pratica.",distinction:"Rendere esplicito un presupposto non basta a confutarlo: occorre valutarne la giustificazione."},
{term:"Qualia",area:"Filosofia della mente",definition:"Caratteristiche qualitative soggettive dell'esperienza, come il modo in cui appare un colore o si sente un dolore.",distinction:"Il dibattito riguarda se e come tali aspetti siano spiegabili in termini fisici e funzionali."},
{term:"Realismo",area:"Metafisica e teoria della conoscenza",definition:"Famiglia di posizioni secondo cui almeno alcuni oggetti, fatti o valori esistono indipendentemente dalle nostre credenze o descrizioni.",distinction:"Realismo scientifico, morale e metafisico sono tesi distinte e non vanno confuse."},
{term:"Riconoscimento",area:"Etica e filosofia politica",definition:"Relazione attraverso cui individui e gruppi vengono riconosciuti come soggetti dotati di dignità, diritti e capacità di partecipazione.",distinction:"Non coincide con l'approvazione: si può riconoscere qualcuno anche dissentendo dalle sue idee."},
{term:"Riduzionismo",area:"Filosofia della scienza e della mente",definition:"Strategia teorica che spiega fenomeni complessi attraverso livelli più fondamentali, oppure identifica un tipo di realtà con un altro.",distinction:"Non ogni spiegazione per parti è riduzionista: il riduzionismo forte sostiene una dipendenza esplicativa o ontologica più radicale."},
{term:"Scetticismo",area:"Teoria della conoscenza",definition:"Famiglia di posizioni che mette in dubbio la possibilità, la portata o la giustificazione della conoscenza in determinati ambiti.",distinction:"Lo scetticismo può essere metodico, globale, locale o pratico: non implica sempre negare ogni conoscenza."},
{term:"Senso comune",area:"Teoria della conoscenza",definition:"Insieme di credenze e capacità condivise che orientano la vita ordinaria e fungono spesso da punto di partenza per la riflessione filosofica.",distinction:"Non è infallibile né necessariamente irrazionale: può contenere conoscenze pratiche e pregiudizi."},
{term:"Sillogismo",area:"Logica",definition:"Forma di ragionamento deduttivo in cui da due premesse segue una conclusione secondo una struttura determinata, studiata sistematicamente da Aristotele.",distinction:"Non ogni deduzione è un sillogismo: la logica moderna comprende forme inferenziali più ampie."},
{term:"Sofisma",area:"Logica e retorica",definition:"Ragionamento apparentemente valido o persuasivo che contiene un errore o mira a indurre in inganno.",distinction:"Va distinto dall'errore involontario: il termine può implicare un uso strategico della fallacia."},
{term:"Soggettività",area:"Filosofia della mente e sociale",definition:"Condizione dell'essere soggetto di esperienza, conoscenza, azione e responsabilità. Le teorie discutono come si costituisca e quanto dipenda da linguaggio e relazioni.",distinction:"Non coincide con arbitrio individuale né con semplice interiorità privata."},
{term:"Solipsismo",area:"Metafisica e filosofia della mente",definition:"Posizione estrema secondo cui soltanto il proprio soggetto o la propria esperienza è certo o esistente.",distinction:"Può essere una tesi ontologica oppure un problema epistemologico sulla conoscenza delle altre menti."},
{term:"Stato di natura",area:"Filosofia politica",definition:"Scenario teorico che descrive la condizione umana prima o al di fuori dell'ordine politico, usato per ragionare su autorità, diritti e obblighi.",distinction:"Non è necessariamente una ricostruzione storica: spesso è un esperimento concettuale."},
{term:"Strutturalismo",area:"Filosofia contemporanea",definition:"Approccio che interpreta fenomeni culturali e sociali attraverso sistemi di relazioni e differenze che precedono i singoli elementi.",distinction:"Non sostiene semplicemente che gli individui non contino: sposta l'attenzione sulle strutture che rendono possibili significati e pratiche."},
{term:"Sublime",area:"Estetica",definition:"Esperienza di grandezza, potenza o intensità che eccede le capacità ordinarie dell'immaginazione e mette in tensione sensibilità e ragione.",distinction:"Si distingue dal bello: il sublime può includere disorientamento, timore e senso del limite."},
{term:"Svolta linguistica",area:"Filosofia contemporanea",definition:"Orientamento che attribuisce al linguaggio un ruolo centrale nell'analisi dei problemi filosofici, della conoscenza e del significato.",distinction:"Non indica una singola scuola: comprende programmi analitici, ermeneutici e altri approcci."},
{term:"Trascendentale",area:"Filosofia moderna",definition:"Indagine sulle condizioni a priori che rendono possibile l'esperienza o la conoscenza. In Kant riguarda le forme e le strutture del soggetto conoscente.",distinction:"Non significa trascendente: il trascendentale riguarda condizioni di possibilità, non realtà oltre l'esperienza."},
{term:"Universalismo",area:"Etica e politica",definition:"Tesi secondo cui alcuni principi, diritti o criteri possono valere per tutti gli esseri umani, indipendentemente da appartenenze particolari.",distinction:"Non implica necessariamente uniformità culturale: universalità di diritti e omogeneità di stili di vita sono cose diverse."},
{term:"Utopia",area:"Filosofia politica",definition:"Rappresentazione critica o progettuale di un ordine sociale alternativo, usata per mettere in discussione istituzioni esistenti e immaginare possibilità diverse.",distinction:"Non è soltanto un progetto irrealizzabile: può funzionare come criterio critico del presente."},
{term:"Validità",area:"Logica e teoria della conoscenza",definition:"Proprietà di un argomento la cui conclusione segue dalle premesse secondo la forma inferenziale, indipendentemente dalla verità effettiva delle premesse.",distinction:"Validità e verità sono distinte: un argomento valido può partire da premesse false."},
{term:"Volontarismo",area:"Metafisica ed etica",definition:"Orientamento che attribuisce alla volontà un ruolo fondamentale nella spiegazione dell'azione, della libertà o dell'ordine morale.",distinction:"Le forme teologiche, politiche e psicologiche del volontarismo non sono equivalenti."},
{term:"Weltanschauung",area:"Filosofia della cultura",definition:"Visione complessiva del mondo che organizza idee, valori e interpretazioni di un'epoca o di un soggetto.",distinction:"Non è necessariamente una teoria coerente: può comprendere convinzioni implicite e pratiche quotidiane."}
,
{term:"Acosmismo",area:"Metafisica",definition:"Posizione che nega realtà autonoma al mondo finito rispetto all'unico principio assoluto, oppure interpreta la molteplicità come priva di consistenza ultima.",distinction:"Non coincide sempre con il semplice idealismo: il termine è usato in contesti storici e polemici differenti."},
{term:"Adab",area:"Filosofia islamica e cultura",definition:"Insieme di educazione, cultura, buone maniere e formazione intellettuale; nella tradizione araba indica anche un ideale di persona colta e socialmente responsabile.",distinction:"Non è riducibile al galateo: comprende saperi, disposizioni morali e pratiche di comunicazione."},
{term:"Ahl al-ra'y",area:"Tradizioni islamiche",definition:"Espressione riferita a orientamenti che attribuiscono un ruolo significativo al ragionamento e alla valutazione giuridica nell'interpretazione normativa.",distinction:"Non designa una scuola unica e il suo significato varia secondo epoca e controversia."},
{term:"Ahl al-hadith",area:"Tradizioni islamiche",definition:"Orientamento che sottolinea l'autorità delle tradizioni profetiche e la trasmissione dei testi nella formulazione della dottrina e del diritto.",distinction:"Non implica necessariamente assenza di ragionamento: riguarda il fondamento e i limiti dell'interpretazione."},
{term:"Apofatismo",area:"Filosofia della religione",definition:"Metodo teologico che procede riconoscendo ciò che non può essere attribuito adeguatamente a Dio, per evitare di ridurre il divino a un oggetto concettuale.",distinction:"Non è semplice agnosticismo: può accompagnarsi a una forma intensa di esperienza e conoscenza religiosa."},
{term:"Ash'arismo",area:"Teologia islamica",definition:"Tradizione teologica sunnita che sviluppa un uso disciplinato della ragione per discutere gli attributi divini, la creazione e la responsabilità umana.",distinction:"Le sue formulazioni mutano nel tempo e non vanno confuse con una posizione uniforme su ogni problema."},
{term:"Attributi divini",area:"Filosofia della religione",definition:"Qualità predicate di Dio, come conoscenza, volontà, potenza e vita; il loro statuto solleva questioni sul rapporto tra unità divina e molteplicità dei nomi.",distinction:"Distinguere il linguaggio sugli attributi dalla loro interpretazione letterale o metaforica."},
{term:"Avicenismo",area:"Storia della filosofia",definition:"Insieme di sviluppi, commenti e trasformazioni delle dottrine di Avicenna nella filosofia islamica, ebraica e latina.",distinction:"Non è una scuola omogenea: include adesioni, correzioni e critiche del sistema avicenniano."},
{term:"Bāṭin",area:"Tradizioni islamiche",definition:"Il senso interiore o nascosto di un testo o di una pratica, distinto dal suo significato esteriore, in alcune tradizioni esegetiche islamiche.",distinction:"Non comporta sempre il rifiuto del significato letterale: i rapporti tra esteriore e interiore variano."},
{term:"Barzakh",area:"Filosofia islamica",definition:"Termine che indica una soglia o condizione intermedia; in contesti filosofici e mistici può descrivere una realtà di mediazione tra ordini differenti.",distinction:"Non ha un solo significato tecnico valido in tutte le tradizioni."},
{term:"Causalità secondaria",area:"Metafisica e teologia",definition:"Riconoscimento di cause create o finite che producono effetti reali pur dipendendo, in ultima istanza, da un fondamento primo.",distinction:"Va distinta dall'occasionalismo, che riduce il ruolo causale autonomo delle creature."},
{term:"Creazione dal nulla",area:"Metafisica e teologia",definition:"Dottrina secondo cui il mondo dipende radicalmente da un atto creativo e non da una materia indipendente preesistente.",distinction:"Non equivale necessariamente a sostenere che la creazione sia avvenuta in un primo istante temporale."},
{term:"Emanazione",area:"Metafisica",definition:"Modello secondo cui la molteplicità deriva da un principio primo attraverso una processione ordinata di livelli di realtà.",distinction:"Non coincide automaticamente con una creazione volontaria nel tempo."},
{term:"Epektasis",area:"Filosofia cristiana",definition:"Movimento di progressione spirituale senza termine definitivo, perché il bene infinito non può essere esaurito da una creatura finita.",distinction:"Non indica un progresso puramente quantitativo o un perfezionamento tecnico."},
{term:"Falsafa",area:"Filosofia islamica",definition:"Tradizione filosofica in lingua araba che rielabora soprattutto Platone, Aristotele e il neoplatonismo in dialogo con teologia e scienze.",distinction:"Non coincide con l'intero pensiero intellettuale islamico, che comprende anche kalām, diritto e mistiche."},
{term:"Fiqh",area:"Filosofia del diritto e Islam",definition:"Comprensione e interpretazione della normativa islamica attraverso metodi giuridici sviluppati dalle diverse scuole.",distinction:"Non è identico alla shari'a: indica soprattutto l'elaborazione umana e interpretativa della norma."},
{term:"Hadith",area:"Tradizioni islamiche",definition:"Racconto relativo a detti, azioni o approvazioni del profeta Muhammad, trasmesso attraverso catene di narratori e sottoposto a valutazione critica.",distinction:"Va distinto dal Corano e considerato secondo i criteri di autenticità e interpretazione."},
{term:"Hikma",area:"Filosofia islamica",definition:"Sapienza o saggezza; in alcuni contesti indica la conoscenza filosofica e la comprensione dei principi della realtà.",distinction:"Non ha sempre un significato tecnico univoco: può riferirsi a sapere, prudenza o sapienza divina."},
{term:"Ijtihad",area:"Filosofia del diritto",definition:"Sforzo interpretativo autonomo compiuto da un giurista qualificato per formulare un giudizio in questioni normative.",distinction:"Non è libertà arbitraria di inventare norme: opera entro metodi e criteri riconosciuti."},
{term:"Imamato",area:"Filosofia politica e religione",definition:"Principio e istituzione della guida della comunità, con significati differenti nelle tradizioni sunnite e sciite.",distinction:"Non va identificato senza distinzioni con il semplice governo politico o con il ruolo del sacerdote."},
{term:"Increato",area:"Filosofia della religione",definition:"Qualifica di ciò che non dipende da un atto creativo e non ha origine in un altro ente; nelle teologie monoteistiche è riferita in modo eminente a Dio.",distinction:"Le controversie sull'increato possono riguardare anche il linguaggio, la parola divina e gli attributi."},
{term:"Intelletto agente",area:"Metafisica e psicologia filosofica",definition:"Principio che rende attuali e intelligibili le forme potenzialmente presenti nella conoscenza umana, secondo diverse interpretazioni aristoteliche e avicenniane.",distinction:"Le scuole divergono sul suo statuto: facoltà dell'anima, principio separato o realtà cosmica."},
{term:"Ishraq",area:"Filosofia islamica",definition:"Tradizione illuminativa associata a Suhrawardi, che combina argomentazione filosofica, simbolismo della luce e conoscenza intuitiva.",distinction:"Non è un semplice irrazionalismo: l'intuizione si affianca a una rigorosa costruzione concettuale."},
{term:"Kalām",area:"Teologia islamica",definition:"Disciplina teologica argomentativa che discute razionalmente questioni come unità divina, attributi, creazione, profezia e libertà umana.",distinction:"Non coincide con la falsafa: ha metodi, obiettivi e genealogie proprie, pur dialogando con essa."},
{term:"Kasb",area:"Teologia islamica",definition:"Dottrina dell'acquisizione dell'atto, elaborata per spiegare come l'azione umana sia attribuibile alla persona pur dipendendo dalla creazione divina.",distinction:"Le interpretazioni differiscono e il concetto non si riduce a un determinismo semplice."},
{term:"Maqasid",area:"Filosofia del diritto",definition:"Fini o obiettivi generali della normativa islamica, impiegati per interpretare le norme alla luce di beni e interessi fondamentali.",distinction:"Non autorizza qualsiasi interpretazione utilitaristica: il rapporto con i testi e i metodi giuridici resta centrale."},
{term:"Maturidismo",area:"Teologia islamica",definition:"Tradizione teologica sunnita che attribuisce alla ragione un ruolo importante nella conoscenza di Dio e nella discussione della responsabilità umana.",distinction:"Condivide temi con l'ash'arismo ma non ne ripete tutte le soluzioni."},
{term:"Miṣbāḥ",area:"Filosofia e simbolismo",definition:"Immagine della lampada, usata in alcuni contesti filosofici e religiosi per rappresentare illuminazione, conoscenza e manifestazione.",distinction:"Il simbolo assume significati diversi e non costituisce da solo una dottrina unitaria."},
{term:"Occasionalismo",area:"Metafisica e teologia",definition:"Tesi secondo cui gli eventi creati non sono cause efficienti autonome: è Dio a produrre direttamente gli effetti in occasione di determinate circostanze.",distinction:"Non significa che gli eventi siano casuali o privi di regolarità osservabili."},
{term:"Qiyās",area:"Logica e diritto",definition:"Ragionamento analogico o inferenziale che estende un giudizio a un caso nuovo sulla base di una causa o caratteristica condivisa.",distinction:"Il suo uso giuridico e quello logico non sono perfettamente sovrapponibili."},
{term:"Rivelazione",area:"Filosofia della religione",definition:"Comunicazione di una verità o volontà divina agli esseri umani, attraverso profeti, testi o esperienze riconosciute da una tradizione religiosa.",distinction:"Va distinta dalla conoscenza naturale e dalle interpretazioni storiche dei testi rivelati."},
{term:"Ta'wil",area:"Ermeneutica e tradizioni islamiche",definition:"Interpretazione che ricerca un significato ulteriore o riconduce un'espressione al suo senso appropriato, soprattutto quando la lettura immediata crea difficoltà.",distinction:"Non equivale sempre ad allegoria libera: i criteri e i limiti variano tra scuole."},
{term:"Tanzih",area:"Teologia islamica",definition:"Principio di incomparabilità e trascendenza divina, che nega l'assimilazione di Dio alle creature.",distinction:"Va pensato insieme alle dottrine degli attributi, non come semplice negazione di ogni predicazione."},
{term:"Tashbih",area:"Teologia islamica",definition:"Linguaggio di somiglianza o comparazione tra Dio e le creature, discusso nelle controversie sugli attributi divini.",distinction:"Non coincide sempre con antropomorfismo letterale: occorre distinguere i diversi usi teologici."},
{term:"Tawhid",area:"Filosofia e teologia islamica",definition:"Affermazione dell'unicità divina, principio fondamentale che orienta metafisica, teologia e pratica religiosa islamica.",distinction:"Non è soltanto monoteismo numerico: implica conseguenze sul rapporto tra Dio, mondo e culto."},
{term:"Wujud",area:"Metafisica islamica",definition:"Termine arabo per esistenza o essere, centrale nelle discussioni metafisiche sull'essere necessario, gli enti possibili e il rapporto tra essenza ed esistenza.",distinction:"Le traduzioni non sono intercambiabili in ogni autore: il significato dipende dal sistema filosofico."},
{term:"Abduzione",area:"Logica e metodo",definition:"Inferenza che formula un'ipotesi capace di spiegare un fatto osservato. È una strategia di scoperta: propone la spiegazione più promettente, che dovrà poi essere controllata.",distinction:"Non garantisce la verità della conclusione come una deduzione valida."},
{term:"Acculturazione",area:"Filosofia della cultura",definition:"Processo di trasformazione che si produce quando gruppi e tradizioni entrano in contatto continuativo, scambiando pratiche, istituzioni e significati. Può comportare appropriazione, conflitto e asimmetrie di potere.",distinction:"Non coincide necessariamente con assimilazione: gli scambi possono essere selettivi e reciproci, anche se non sempre paritari."},
{term:"Acosmismo",area:"Metafisica e religione",definition:"Posizione secondo cui il mondo finito non possiede realtà autonoma rispetto all'assoluto o al principio divino. Il termine è usato soprattutto nelle interpretazioni di alcune forme di idealismo e misticismo.",distinction:"Non è identico al nichilismo: può affermare la realtà dell'assoluto proprio mentre ridimensiona quella del mondo finito."},
{term:"Affectus",area:"Etica e filosofia della mente",definition:"In Spinoza indica le modificazioni del corpo e le idee di tali modificazioni, attraverso cui aumenta o diminuisce la potenza di agire. Gli affetti sono parte della dinamica concreta dell'esistenza.",distinction:"Non coincide con una semplice emozione soggettiva: ha una dimensione corporea, causale e relazionale."},
{term:"Agape",area:"Etica e filosofia della religione",definition:"Amore inteso come benevolenza e dono non riducibile al possesso o alla reciprocità contrattuale. Nella tradizione cristiana assume un significato teologico ed etico specifico.",distinction:"Va distinta da eros, pur potendo le due forme di amore essere messe in relazione."},
{term:"Agnosticismo",area:"Filosofia della religione",definition:"Posizione che sospende o nega la possibilità di conoscere con certezza l'esistenza di realtà divine o trascendenti. Può assumere forme moderate o radicali.",distinction:"Non equivale all'ateismo: riguarda anzitutto i limiti della conoscenza, non necessariamente la negazione di Dio."},
{term:"Akrasia",area:"Etica antica",definition:"Debolezza della volontà per cui una persona agisce contro il giudizio che riconosce come migliore, cedendo a desideri o impulsi concorrenti.",distinction:"Non è semplice ignoranza morale: il problema è spiegare perché il giudizio corretto non governi l'azione."},
{term:"Anamnesi",area:"Filosofia antica",definition:"In Platone, processo del ricordare conoscenze che l'anima avrebbe acquisito prima della vita incarnata. La dottrina collega apprendimento, conoscenza e immortalità dell'anima.",distinction:"Non è memoria autobiografica ordinaria, ma una teoria filosofica delle condizioni della conoscenza."},
{term:"Anarchia",area:"Filosofia politica",definition:"Assenza di un potere sovrano centralizzato o progetto di organizzazione sociale senza dominio gerarchico coercitivo. Le teorie anarchiche propongono forme differenti di cooperazione e autogoverno.",distinction:"Non significa necessariamente caos o assenza di regole: molte prospettive anarchiche valorizzano norme condivise e istituzioni volontarie."},
{term:"Antropocentrismo",area:"Etica e filosofia della natura",definition:"Orientamento che assume l'essere umano come centro privilegiato di valore, conoscenza o organizzazione del mondo. Può fondare diritti e responsabilità, ma anche subordinare la natura agli interessi umani.",distinction:"Si distingue dal biocentrismo e dall'ecocentrismo, che attribuiscono valore morale rispettivamente alla vita e agli ecosistemi."},
{term:"Apatheia",area:"Filosofia ellenistica",definition:"Nello stoicismo indica la libertà dalle passioni intese come giudizi irrazionali e disordinati. Non comporta insensibilità, ma una trasformazione del rapporto con gli eventi e con il giudizio.",distinction:"Non va confusa con l'apatia moderna intesa come indifferenza o mancanza di motivazione."},
{term:"Arché",area:"Filosofia antica",definition:"Principio originario o fondamento da cui le cose derivano e attraverso cui possono essere spiegate. I presocratici individuarono archai differenti, dalla materia all'illimitato o al logos.",distinction:"Non indica sempre un inizio temporale: può designare una condizione esplicativa o ontologica."},
{term:"Areté",area:"Etica antica",definition:"Eccellenza o virtù: realizzazione adeguata delle capacità proprie di un essere o di una persona. Nel pensiero greco assume significati etici, politici e conoscitivi.",distinction:"Non coincide soltanto con la virtù morale nel senso moderno: può indicare competenza ed eccellenza in una funzione."},
{term:"Assiologia",area:"Etica e filosofia dei valori",definition:"Indagine filosofica sulla natura dei valori, sui modi in cui qualcosa può essere considerato buono, giusto, bello o desiderabile e sulle relazioni tra valori differenti.",distinction:"Non è sinonimo di etica: comprende anche valori estetici, epistemici e culturali."},
{term:"Autopoiesi",area:"Filosofia della biologia e della mente",definition:"Concetto che descrive sistemi capaci di produrre e mantenere continuamente la propria organizzazione attraverso le proprie operazioni. È stato sviluppato nello studio dei sistemi viventi e ripreso nelle teorie della cognizione.",distinction:"Non equivale ad autosufficienza assoluta: un sistema autopoietico resta in rapporto materiale ed energetico con l'ambiente."},
{term:"Biopolitica",area:"Filosofia politica contemporanea",definition:"Analisi delle forme di potere che prendono come oggetto la vita biologica delle popolazioni: salute, nascita, mortalità, igiene, sessualità e gestione dei corpi.",distinction:"Non coincide con ogni politica sanitaria: riguarda il modo in cui sapere e potere organizzano la vita individuale e collettiva."},
{term:"Catarsi",area:"Estetica e filosofia antica",definition:"Purificazione, chiarificazione o trasformazione delle passioni. Nella Poetica di Aristotele è collegata agli effetti della tragedia attraverso pietà e paura, ma la sua interpretazione resta discussa.",distinction:"Non ha un significato univoco: le letture mediche, morali ed estetiche non sono sovrapponibili."},
{term:"Certezza",area:"Epistemologia",definition:"Condizione in cui un soggetto considera una proposizione immune da dubbio o sufficientemente fondata. La filosofia distingue certezza psicologica, logica, pratica e giustificata.",distinction:"Sentirsi certi non significa possedere una conoscenza vera o adeguatamente giustificata."},
{term:"Comunitarismo",area:"Filosofia politica",definition:"Famiglia di teorie che sottolineano il ruolo delle comunità, delle pratiche condivise e delle tradizioni nella formazione dell'identità e dei giudizi morali.",distinction:"Non implica necessariamente il rifiuto dei diritti individuali: contesta soprattutto l'immagine dell'individuo come soggetto formato indipendentemente dai legami sociali."},
{term:"Contingenza",area:"Metafisica",definition:"Carattere di ciò che può essere o accadere diversamente, o anche non essere. La contingenza si contrappone alla necessità e pone il problema delle condizioni che rendono attuale una possibilità.",distinction:"Non equivale a casualità: qualcosa può essere contingente e tuttavia avere cause determinate."},
{term:"Contraddizione",area:"Logica e dialettica",definition:"Relazione tra proposizioni o determinazioni incompatibili nello stesso rispetto. Nella logica classica una proposizione e la sua negazione non possono essere entrambe vere nello stesso senso.",distinction:"La contrarietà non coincide sempre con la contraddizione: due tesi contrarie possono essere entrambe false."},
{term:"Deontologia",area:"Etica",definition:"Teoria morale che valuta le azioni in rapporto a doveri, principi e vincoli, non soltanto in base alle conseguenze prodotte.",distinction:"Non significa semplicemente codice professionale: designa una famiglia di teorie normative."},
{term:"Elenchos",area:"Filosofia antica",definition:"Procedura socratica di confutazione che esamina le convinzioni dell'interlocutore e mostra eventuali incoerenze tra le sue affermazioni.",distinction:"Non è una disputa volta a prevalere: idealmente mira a verificare la coerenza delle credenze e a favorire la ricerca."},
{term:"Emergentismo",area:"Metafisica e filosofia della scienza",definition:"Posizione secondo cui sistemi complessi possono manifestare proprietà o capacità nuove, non facilmente riducibili alle proprietà delle loro componenti isolate.",distinction:"Non implica necessariamente dualismo: alcune forme di emergentismo restano naturalistiche."},
{term:"Entelechia",area:"Metafisica e filosofia della natura",definition:"In Aristotele indica il compimento o l'attualità di ciò che possiede in sé il principio della propria realizzazione. È connessa al rapporto tra potenza e atto.",distinction:"Non è una forza misteriosa separata: designa il compimento di una forma o capacità."},
{term:"Epoche",area:"Scetticismo e fenomenologia",definition:"Sospensione del giudizio o messa tra parentesi di assunzioni abituali. Nello scetticismo antico mira alla sospensione dell'assenso; in Husserl assume una funzione metodologica.",distinction:"Non è semplice indecisione: è una pratica filosofica con finalità diverse secondo le tradizioni."},
{term:"Ermeneutica",area:"Filosofia del linguaggio e della cultura",definition:"Teoria e pratica dell'interpretazione di testi, azioni, simboli e tradizioni. Nella filosofia contemporanea diventa anche riflessione sulle condizioni storiche e linguistiche della comprensione.",distinction:"Non è una tecnica applicata soltanto ai testi sacri: riguarda ogni processo in cui il significato deve essere interpretato."},
{term:"Fatalismo",area:"Metafisica e filosofia dell'azione",definition:"Tesi secondo cui determinati eventi si verificheranno indipendentemente da ciò che gli agenti fanno o decidono. Può fondarsi su destino, necessità o interpretazioni della predestinazione.",distinction:"Non coincide con determinismo: nel determinismo le azioni possono essere cause degli eventi, mentre il fatalismo tende a renderle irrilevanti rispetto all'esito."},
{term:"Genealogia",area:"Filosofia contemporanea",definition:"Metodo critico che ricostruisce la formazione storica di concetti, valori e istituzioni, mostrando conflitti, pratiche e rapporti di potere che ne hanno reso possibile l'affermazione.",distinction:"Non è una semplice cronologia delle origini: interroga gli effetti e le contingenze di ciò che appare naturale."},
{term:"Habitus",area:"Filosofia sociale",definition:"Insieme di disposizioni durevoli, incorporate attraverso l'esperienza, che orientano percezioni, gusti e pratiche. In Bourdieu collega struttura sociale e condotta individuale.",distinction:"Non è un'abitudine isolata né un destino immutabile: le disposizioni sono durevoli ma possono trasformarsi."},
{term:"Intersoggettività",area:"Fenomenologia e filosofia sociale",definition:"Dimensione dell'esperienza e della conoscenza che si costituisce nel rapporto tra soggetti. Riguarda il riconoscimento reciproco, la comunicazione e la possibilità di un mondo condiviso.",distinction:"Non è la semplice somma di prospettive individuali: concerne le condizioni che rendono possibile la reciprocità."},
{term:"Ontoteologia",area:"Metafisica e filosofia della religione",definition:"Struttura del pensiero metafisico che interpreta l'essere a partire da un ente supremo o da un fondamento assoluto, unendo interrogazione ontologica e teologica.",distinction:"Non coincide con ogni discorso su Dio: indica una specifica configurazione del rapporto tra essere e fondamento."},
{term:"Panpsichismo",area:"Filosofia della mente",definition:"Famiglia di teorie secondo cui la dimensione mentale o esperienziale è una caratteristica fondamentale e diffusa della realtà, non esclusiva degli organismi complessi.",distinction:"Non sostiene necessariamente che ogni cosa abbia coscienza riflessiva o pensieri simili a quelli umani."},
{term:"Qualia",area:"Filosofia della mente",definition:"Caratteri qualitativi soggettivi dell'esperienza, come il modo in cui appare un colore o si avverte un dolore. Sono al centro del problema del rapporto tra esperienza cosciente e descrizione fisica.",distinction:"Non coincidono con gli oggetti percepiti: riguardano il carattere vissuto dell'esperienza."},
{term:"Riconoscimento",area:"Etica e filosofia politica",definition:"Relazione attraverso cui individui e gruppi vedono riconosciuti identità, diritti e capacità da altri soggetti e dalle istituzioni. È centrale nelle teorie di Hegel e in numerosi dibattiti contemporanei.",distinction:"Non equivale ad approvazione: si può riconoscere l'eguale dignità di qualcuno senza condividere le sue idee."},
{term:"Riduzionismo",area:"Filosofia della scienza",definition:"Strategia teorica che spiega fenomeni complessi attraverso processi o leggi di un livello considerato più fondamentale. Può riguardare ontologia, metodo o spiegazione.",distinction:"Ridurre una spiegazione non significa sempre negare l'utilità dei livelli superiori di analisi."},
{term:"Sublime",area:"Estetica",definition:"Esperienza estetica legata a grandezza, potenza o immensità che eccedono la misura ordinaria dell'immaginazione. In Kant il sublime mette in luce insieme il limite della sensibilità e una facoltà razionale che lo oltrepassa.",distinction:"Si distingue dal bello, che si lega più direttamente a forma, misura e armonia."},
{term:"Svolta linguistica",area:"Filosofia del linguaggio",definition:"Orientamento novecentesco che attribuisce al linguaggio un ruolo centrale nell'analisi dei problemi filosofici. Le questioni su conoscenza, realtà e mente vengono esaminate anche attraverso strutture e usi linguistici.",distinction:"Non è una scuola unitaria: comprende approcci analitici, pragmatici, strutturalisti e altre prospettive."},
{term:"Trascendentale",area:"Epistemologia e metafisica",definition:"Indagine sulle condizioni a priori che rendono possibile l'esperienza o la conoscenza. In Kant riguarda le strutture del soggetto che organizzano ogni esperienza possibile.",distinction:"Non significa trascendente: il trascendentale riguarda le condizioni dell'esperienza, il trascendente ciò che la oltrepasserebbe."},
{term:"Universalismo",area:"Etica e politica",definition:"Posizione secondo cui determinati principi, diritti o criteri di validità possono valere per tutti gli esseri umani, al di là delle differenze culturali e storiche.",distinction:"Va distinto dall'imposizione di un modello particolare presentato come universale: la pretesa universalistica deve giustificare inclusione e reciprocità."}
];

const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("");
export default function LexiconPage() {
  const [query, setQuery] = useState("");
  const [area, setArea] = useState("Tutte le aree");
  const filtered = useMemo(() => {
    const q = query.trim().toLocaleLowerCase("it");
    return terms.filter((item) => (area === "Tutte le aree" || item.area === area) && (!q || [item.term,item.area,item.definition,item.distinction].join(" ").toLocaleLowerCase("it").includes(q)));
  }, [query, area]);
  const areas = ["Tutte le aree", ...Array.from(new Set(terms.map((item) => item.area))).sort((a,b)=>a.localeCompare(b,"it"))];
  const groups = alphabet.map((letter) => ({letter,items:filtered.filter((item)=>item.term.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLocaleUpperCase("it").startsWith(letter))})).filter((group)=>group.items.length);
  return <main className="lexicon-page">
    <header className="site-header"><Link className="brand" href="/"><span className="brand-mark">Φ</span><span><strong>Dizionario filosofico</strong><small>Storia universale del pensiero</small></span></Link><nav aria-label="Navigazione principale"><Link href="/enciclopedia">Enciclopedia</Link><Link href="/cronologie">Cronologie</Link><Link href="/indici">Indici</Link><Link href="/">Home</Link></nav></header>
    <section className="lexicon-hero"><p className="eyebrow">Strumento di consultazione</p><h1>Lessico filosofico</h1><p>Parole, concetti e distinzioni per orientarsi tra le tradizioni del pensiero. Le definizioni indicano i principali usi storici senza presumere che un termine abbia sempre lo stesso significato.</p><div className="lexicon-count"><strong>{filtered.length}</strong><span>di {terms.length} termini</span></div></section>
    <div className="section-wrap lexicon-content">
      <div className="lexicon-search"><label htmlFor="lexicon-search">Cerca un termine o una definizione</label><input id="lexicon-search" type="search" placeholder="Es. essere, dharma, dialettica…" value={query} onChange={(event)=>setQuery(event.target.value)}/><label htmlFor="lexicon-area">Ambito</label><select id="lexicon-area" value={area} onChange={(event)=>setArea(event.target.value)}>{areas.map((item)=><option key={item}>{item}</option>)}</select></div>
      <nav className="lexicon-letters" aria-label="Indice alfabetico">{alphabet.map((letter)=><a key={letter} className={groups.some((group)=>group.letter===letter)?"":"disabled"} href={groups.some((group)=>group.letter===letter?true:false)?`#letter-${letter}`:undefined}>{letter}</a>)}</nav>
      {groups.length ? groups.map((group)=><section className="lexicon-letter" id={`letter-${group.letter}`} key={group.letter}><h2>{group.letter}</h2><div className="lexicon-terms">{group.items.map((item)=><article className="lexicon-term" key={item.term}><div className="lexicon-term-heading"><h3>{item.term}</h3><span>{item.area}</span></div><p>{item.definition}</p><p className="lexicon-distinction"><strong>Da distinguere:</strong> {item.distinction}</p>{item.related?.length ? <div className="lexicon-related">{item.related.map((link)=><Link href={`/enciclopedia/${link.slug}`} key={link.slug}>{link.label} ↗</Link>)}</div>:null}</article>)}</div></section>):<p className="empty-state">Nessun termine corrisponde alla ricerca. Prova un’altra parola o modifica l’ambito.</p>}
      <p className="editorial-note">Lessico in ampliamento. I termini sono definiti nel loro contesto storico e culturale; le traduzioni sono orientative e non sostituiscono l’uso specifico nelle singole tradizioni.</p>
    </div>
    <footer className="site-footer"><span>© {new Date().getFullYear()} Dizionario universale della storia della filosofia</span><span>Lessico filosofico · Edizione iniziale</span></footer>
  </main>;
}
